      'Тарангире открывает поездку настоящим отдельным полднём, плюс остановкой в Мто-ва-Мбу и визитом в масайскую общину, встроенными в маршрут, а не пристёгнутыми к нему, — парк держит одну из крупнейших популяций слонов Восточной Африки, концентрирующихся вдоль реки в сухой сезон. Кратеру Нгоронгоро отведён полный день, а не спешная утренняя остановка: обрушившаяся вулканическая кальдера площадью примерно 260 км², со стенами настолько крутыми, что большая часть обитающих внутри животных никогда её не покидает, — и один из самых насыщенных дней наблюдения за дикой природой на всём маршруте. Далее следуют два полных дня на территории оседлых хищников Серенгети, прежде чем живописный перелёт — с промежуточной посадкой в Аруше — меняет автомобиль на открытую воду и три ничем не занятые ночи на белом песке Нунгви.',
